/* All entries are programmed.
 * Keep the RLB bit so that dynamic mappings can be done.
 */

/* M-mode only access regions are always locked */
pmp_flags |= PMP_L;
if (reg->flags & SBI_DOMAIN_MEMREGION_M_READABLE)
    pmp_flags |= PMP_R;
if (reg->flags & SBI_DOMAIN_MEMREGION_M_WRITABLE)
    pmp_flags |= PMP_W;

cfgmask = ~(0xffUL << pmpcfg_shift);
pmpcfg  = (csr_read_num(pmpcfg_csr) & cfgmask);
csr_write_num(pmpcfg_csr, pmpcfg);
return SBI_OK;

struct sbi_hsm_data {
    atomic_t state;
    unsigned long suspend_type;
    unsigned long saved_mie;
    unsigned long saved_mip;
    unsigned long saved_medeleg;
    unsigned long saved_mideleg;
    u64 saved_menvcfg;
    atomic_t start_ticket;
};

hdata->saved_mie = csr_read(CSR_MIE);
hdata->saved_mip = csr_read(CSR_MIP) & (MIP_SSIP | MIP_STIP);
hdata->saved_medeleg = csr_read(CSR_MEDELEG);
hdata->saved_mideleg = csr_read(CSR_MIDELEG);
hdata->saved_menvcfg = csr_read64(CSR_MENVCFG);

csr_write64(CSR_MENVCFG, hdata->saved_menvcfg);
csr_write(CSR_MIDELEG, hdata->saved_mideleg);
csr_write(CSR_MEDELEG, hdata->saved_medeleg);
csr_write(CSR_MIE, hdata->saved_mie);
csr_set(CSR_MIP, (hdata->saved_mip & (MIP_SSIP | MIP_STIP)));

for (i = 0; i < pmp_count; i++) {
    if (sbi_hart_smepmp_is_fw_region(i))
        continue;
    sbi_platform_pmp_disable(sbi_platform_ptr(scratch), i);
    pmp_disable(i);
}

if (sbi_hart_has_extension(scratch, SBI_HART_EXT_ZKR)) {
    csr_set(CSR_MSECCFG, MSECCFG_SSEED);
    csr_clear(CSR_MSECCFG, MSECCFG_USEED);
}
